/**
 * AccentCard — spec §10.1 (Card variant=accent-left), §11.2
 *
 * Card with a 4px primary-blue left border. Used by list pages (e.g. Events list).
 * Supports `interactive` for hover elevation and pointer cursor.
 */
import * as React from 'react';
import { Card, CardProps } from '@mui/material';
import { elevation, motion, radius, semanticColors } from '@/constants/ThemeConstants';

export interface AccentCardProps extends Omit<CardProps, 'variant'> {
    /** When true, applies hover elevation + pointer cursor. */
    interactive?: boolean;
    /** Override the accent color. Defaults to `accent.primary`. */
    accentColor?: string;
}

export const AccentCard: React.FC<AccentCardProps> = ({
    interactive = false,
    accentColor = semanticColors.accent.primary,
    sx,
    children,
    ...rest
}) => (
    <Card
        elevation={0}
        {...rest}
        sx={[
            {
                position: 'relative',
                backgroundColor: semanticColors.surface.card,
                borderRadius: `${radius.md}px`,
                borderLeft: `4px solid ${accentColor}`,
                boxShadow: elevation[1],
                transition: `box-shadow ${motion.fast}ms ease, transform ${motion.fast}ms ease`,
                ...(interactive && {
                    cursor: 'pointer',
                    '&:hover': { boxShadow: elevation[2] },
                    '&:focus-visible': {
                        outline: `2px solid ${semanticColors.accent.primary}`,
                        outlineOffset: 2,
                    },
                    '@media (prefers-reduced-motion: reduce)': {
                        transition: 'none',
                    },
                }),
            },
            ...(Array.isArray(sx) ? sx : [sx]),
        ]}
    >
        {children}
    </Card>
);

export default AccentCard;
