import React from 'react';
import { Chip, Tooltip } from '@mui/material';
import VerifiedIcon from '@mui/icons-material/Verified';
import { compactChipSx } from '@/constants/ThemeConstants';

interface VerifiedBadgeProps {
    /** Renders nothing when false/undefined, so callers can pass the flag directly. */
    verified?: boolean;
    /** Icon only (for dense rows) vs. icon + "Verified" label. */
    iconOnly?: boolean;
    title?: string;
}

/** Trust tag granted by an Admin / School Admin / Batch Admin. */
export const VerifiedBadge: React.FC<VerifiedBadgeProps> = ({ verified, iconOnly = false, title = 'Verified member' }) => {
    if (!verified) return null;

    if (iconOnly) {
        return (
            <Tooltip title={title}>
                <VerifiedIcon color="primary" sx={{ fontSize: '1rem', flexShrink: 0 }} aria-label={title} />
            </Tooltip>
        );
    }

    return (
        <Chip
            icon={<VerifiedIcon sx={{ fontSize: '0.85rem' }} />}
            label="Verified"
            size="small"
            color="primary"
            variant="outlined"
            sx={{ ...compactChipSx }}
        />
    );
};
